version.transform:
(
  /* === CONFIGURATION === */
  $tz := $.tz ? $.tz : $metadata.settings.TimeZone ? $metadata.settings.TimeZone : $momentTzGuess();
  $now := $moment().tz($tz);
  $nowMs := $toMillis($now.format());
  $hourStart := $moment($now).startOf('hour');
  $hourStartMs := $toMillis($hourStart.format());
  $hourEndMs := $hourStartMs + 3600000;
  $last8Start := $moment($hourStart).subtract(7, 'hours');
  $last8StartFmt := $last8Start.format('YYYY-MM-DDTHH:mm:ss.SSSZ');
  $hourStartFmt := $hourStart.format('YYYY-MM-DDTHH:mm:ss.SSSZ');
  $hourEndFmt := $moment($hourStart).add(1, 'hour').format('YYYY-MM-DDTHH:mm:ss.SSSZ');
  $wcId := $.wcId ? $.wcId : $metadata.querystring.wcId ? $metadata.querystring.wcId : "wc-vmc-c1";
  
  /* === QUERY === */
  $statement := 'query($wcId: String!, $startTime: DateTime!, $endTime: DateTime!, $hourEnd: DateTime!) {
    oeeHourly(
      where: {
        _and: [
          { workcenterId: { _eq: $wcId } },
          { periodStartAt: { _gte: $startTime } },
          { periodStartAt: { _lte: $endTime } }
        ]
      },
      orderBy: [{ field: periodStartAt, direction: asc }]
    ) {
      edges {
        node {
          id
          periodStartAt
          availability
          performance
          quality
          scheduledTime(format: milliseconds)
          plannedDowntimeMinutes(format: milliseconds)
          runMinutes(format: milliseconds)
          goodUnits
          totalUnits
          idealUnits
        }
      }
    }
    currentHourHistory: workcenterHistory(
      where: {
        _and: [
          { workcenterId: { _eq: $wcId } },
          { occurAt: { _lte: $hourEnd } },
          { _or: [
            { endAt: { _isNull: true } },
            { endAt: { _gte: $endTime } }
          ]}
        ]
      }
      orderBy: [{ field: occurAt, direction: asc }]
    ) {
      edges {
        node {
          id occurAt endAt
          mode { countAsProductionTime }
        }
      }
    }
  }';
  
  $result := $query({
    "statement": $statement,
    "variables": {
      "wcId": $wcId,
      "startTime": $last8StartFmt,
      "endTime": $hourStartFmt,
      "hourEnd": $hourEndFmt
    }
  });
  
  $records := $result.oeeHourly.edges.node ? $result.oeeHourly.edges.node : [];
  $historyRecs := $result.currentHourHistory.edges.node ? $result.currentHourHistory.edges.node : [];
  
  /* === HELPERS === */
  $n := function($v) {( $v ? $v : 0 )};
  $clamp := function($v) {( $v > 1 ? 1 : ($v < 0 ? 0 : $v) )};
  
  /* Pre-build index of records by hour key */
  $recordsByHour := $reduce($records, function($acc, $r) {(
    $key := $moment($r.periodStartAt).tz($tz).format('YYYY-MM-DDTHH');
    $merge([$acc, { $key: $r }])
  )}, {});
  
  /* Calculate live production time for current hour from workcenterHistory */
  $liveProductionMs := $reduce($historyRecs, function($acc, $r) {(
    $startMs := $toMillis($r.occurAt);
    $endMs := $r.endAt ? $toMillis($r.endAt) : $nowMs;
    $oStart := $startMs < $hourStartMs ? $hourStartMs : $startMs;
    $oEnd := $endMs > $nowMs ? $nowMs : $endMs;
    $oEnd := $oEnd > $hourEndMs ? $hourEndMs : $oEnd;
    $dur := $oEnd > $oStart ? $oEnd - $oStart : 0;
    $acc + ($r.mode.countAsProductionTime ? $dur : 0)
  )}, 0);
  
  /* Get current hour record and calculate live values */
  $currHourKey := $hourStart.format('YYYY-MM-DDTHH');
  $currHourRec := $lookup($recordsByHour, $currHourKey);
  $currScheduledMs := $n($currHourRec.scheduledTime);
  $currIsScheduled := $currScheduledMs > 0;
  $currNeedsLive := $currIsScheduled and ($currHourRec.availability = null or $currHourRec.availability = 0);
  
  $elapsedMs := $nowMs - $hourStartMs;
  $liveA := $clamp($elapsedMs > 0 ? $liveProductionMs / $elapsedMs : 1);
  $liveP := 1;
  $liveQ := $clamp($n($currHourRec.totalUnits) > 0 ? $n($currHourRec.goodUnits) / $currHourRec.totalUnits : 1);
  
  /* === BUILD CHART DATA === */
  $chartData := [0,1,2,3,4,5,6,7].(
    $i := $;
    $slotMoment := $moment($last8Start).add($i, 'hours');
    $slotKey := $slotMoment.format('YYYY-MM-DDTHH');
    $label := $slotMoment.format('h A');
    $isCurrHour := $slotKey = $currHourKey;
    
    /* O(1) lookup */
    $match := $lookup($recordsByHour, $slotKey);
    
    /* Check conditions */
    $scheduledMs := $n($match.scheduledTime);
    $isScheduled := $scheduledMs > 0;
    $isPlannedDowntime := $n($match.plannedDowntimeMinutes) >= 3600000;
    $hasStoredValues := $match.availability != null and $match.availability > 0;
    
    /* Determine which values to use */
    $useLive := $isCurrHour and $currNeedsLive;
    
    /* Calculate metrics */
    $a := $isScheduled = false or $isPlannedDowntime ? null
      : $useLive ? $liveA
      : $hasStoredValues ? $match.availability
      : $clamp($scheduledMs > 0 ? $n($match.runMinutes) / $scheduledMs : 0);
    
    $p := $isScheduled = false or $isPlannedDowntime ? null
      : $useLive ? $liveP
      : $hasStoredValues ? $match.performance
      : $clamp($n($match.idealUnits) > 0 ? $n($match.totalUnits) / $match.idealUnits : 1);
    
    $q := $isScheduled = false or $isPlannedDowntime ? null
      : $useLive ? $liveQ
      : $hasStoredValues ? $match.quality
      : $clamp($n($match.totalUnits) > 0 ? $n($match.goodUnits) / $match.totalUnits : 1);
    
    {
      "label": $label,
      "availability": $a != null ? $round($a * 100, 2) : "NA",
      "performance": $p != null ? $round($p * 100, 2) : "NA",
      "quality": $q != null ? $round($q * 100, 2) : "NA"
    }
  );
  
  /* === BUILD OUTPUT === */
  $categories := $chartData.({ "label": label });
  $availData := $chartData.({ "value": $string(availability) });
  $perfData := $chartData.({ "value": $string(performance) });
  $qualData := $chartData.({ "value": $string(quality) });
  
  /* FusionCharts Output */
  {
    "chart": {
      "caption": "OEE Components - Last 8 Hours",
      "subCaption": "",
      "xAxisName": "",
      "yAxisName": "",
      "yAxisMinValue": "0",
      "yAxisMaxValue": "100",
      "showValues": "1",
      "valueFontSize": "18",
      "plottooltext": "$seriesName: $dataValue%",
      "showShadow": "0",
      "use3DLighting": "0",
      "showCanvasShadow": "0",
      "plotShadow": "0",
      "boxShadow": "0",
      "showBorder": "0",
      "plotFillAlpha": "60",
      "plotBorderThickness": "2",
      "plotBorderAlpha": "100",
      "usePlotGradientColor": "1",
      "plotGradientColor": "#FFFFFF",
      "plotFillAngle": "90",
      "drawAnchors": "1",
      "anchorRadius": "7",
      "anchorBorderThickness": "2",
      "anchorAlpha": "100",
      "anchorSides": "4",
      "showValue": "1",
      "canvasBgColor": "#FFFFFF",
      "canvasBgAlpha": "100",
      "canvasBorderThickness": "0",
      "showCanvasBorder": "0",
      "bgColor": "#FFFFFF",
      "bgAlpha": "100",
      "divLineColor": "#E0E0E0",
      "divLineAlpha": "50",
      "divLineThickness": "1",
      "showAlternateHGridColor": "1",
      "alternateHGridColor": "#F8F8F8",
      "alternateHGridAlpha": "50",
      "xAxisLineColor": "#E0E0E0",
      "yAxisLineColor": "#E0E0E0",
      "xAxisLineThickness": "1",
      "yAxisLineThickness": "1",
      "labelFontColor": "#666666",
      "labelFontSize": "16",
      "yAxisValueFontColor": "#666666",
      "yAxisValueFontSize": "16",
      "xAxisNameFontColor": "#555555",
      "yAxisNameFontColor": "#555555",
      "captionFontColor": "#333333",
      "subCaptionFontColor": "#666666",
      "showLegend": "1",
      "legendPosition": "bottom",
      "legendBgColor": "#FFFFFF",
      "legendBorderAlpha": "0",
      "legendShadow": "0",
      "legendItemFontColor": "#555555",
      "legendItemFontSize": "16",
      "chartLeftMargin": "0",
      "chartRightMargin": "0",
      "chartTopMargin": "0",
      "chartBottomMargin": "0",
      "canvasLeftMargin": "0",
      "canvasRightMargin": "0",
      "canvasTopMargin": "0",
      "canvasBottomMargin": "0",
      "captionPadding": "5",
      "legendPadding": "3",
      "labelPadding": "3",
      "xAxisNamePadding": "5",
      "yAxisNamePadding": "5",
      "drawCrossLine": "1",
      "crossLineColor": "#888888",
      "crossLineAlpha": "30"
    },
    "categories": [{ "category": $categories }],
    "dataset": [
      {
        "seriesname": "Availability",
        "color": "#70AD47",
        "anchorBgColor": "#70AD47",
        "anchorBorderColor": "#5A8A3A",
        "data": $availData
      },
      {
        "seriesname": "Performance",
        "color": "#5B9BD5",
        "anchorBgColor": "#5B9BD5",
        "anchorBorderColor": "#4A7FB0",
        "data": $perfData
      },
      {
        "seriesname": "Quality",
        "color": "#FFC000",
        "anchorBgColor": "#FFC000",
        "anchorBorderColor": "#D9A300",
        "data": $qualData
      }
    ]
  }
)
